function slider(parent, label, value, min, max, step, oninput, opts) {
  const d = document.createElement('div'); d.className = 'ctl';
  const sign = opts && opts.sign ? (opts.sign === -1 ? '&minus; ' : '+ ') : '';
  const ex = EXPLAIN[label] ? ` data-tip="${EXPLAIN[label].replace(/"/g,'&quot;')}"` : '';
  d.innerHTML = `<label><span${ex}>${sign}${label}</span><b></b></label>
    <input type="range" min="${min}" max="${max}" step="${step}" value="${value}">`;
  const b = d.querySelector('b'), inp = d.querySelector('input');
  const show = v => b.textContent = (opts && opts.fmt) ? opts.fmt(v) : (+v).toFixed(2);
  show(value);
  // setters may clamp (e.g. the two cut sliders can't cross): display what was
  // actually applied, not the raw slider position
  inp.addEventListener('input', () => {
    const applied = oninput(+inp.value);
    show(applied !== undefined ? applied : +inp.value);
    schedule();
  });
  parent.appendChild(d);
  return inp;
}
