function quantile(sortedArr, q) {
  const idx = q * (sortedArr.length - 1), lo = Math.floor(idx), hi = Math.ceil(idx);
  return sortedArr[lo] + (sortedArr[hi] - sortedArr[lo]) * (idx - lo);
}
function ranksOf(vals) { // right-ECDF ranks — EXACTLY rank_utils.ecdf_ranks in Python
  const n = vals.length, sorted = Array.from(vals).sort((a, b) => a - b);
  const out = new Float64Array(n);
  if (!n || sorted[0] === sorted[n - 1]) { out.fill(0.5); return out; } // constant -> neutral
  for (let k = 0; k < n; k++) {
    let lo = 0, hi = n; // upper_bound(sorted, vals[k])
    while (lo < hi) { const m = (lo + hi) >> 1; if (sorted[m] <= vals[k]) lo = m + 1; else hi = m; }
    out[k] = lo / n;
  }
  return out;
}
function pearson(a, b) {
  let ma = 0, mb = 0; for (let i = 0; i < a.length; i++) { ma += a[i]; mb += b[i]; }
  ma /= a.length; mb /= a.length;
  let sab = 0, sa = 0, sb = 0;
  for (let i = 0; i < a.length; i++) {
    const x = a[i] - ma, y = b[i] - mb; sab += x * y; sa += x * x; sb += y * y;
  }
  return sab / Math.sqrt(sa * sb || 1);
}
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };
}
function dist2(a, b) { let s = 0; for (let i = 0; i < a.length; i++) { const d = a[i] - b[i]; s += d * d; } return s; }

// group -> column indices in row.rank
const groupIdx = {};
{ let base = 0;
  for (const [g, spec] of Object.entries(M.featureGroups)) {
    groupIdx[g] = { sign: spec.sign, idx: spec.features.map((f, k) => base + k) };
    base += spec.features.length;
  } }

// ML difficulty rank: fixed (out-of-fold cumulative probabilities from the pipeline)
const CUM = R.map(r => r.cum);
const mlDiffRank = ranksOf(CUM.map(c => 1 - (c[0] + c[1]) / 2));

function heuristicScores() {
  const out = new Float64Array(N);
  let tw = 0; for (const g in state.gw) tw += state.gw[g];
  for (let i = 0; i < N; i++) {
    const rk = R[i].rank; let s = 0;
    for (const g in groupIdx) {
      const { sign, idx } = groupIdx[g];
      let m = 0; for (const c of idx) m += rk[c];
      s += sign * state.gw[g] * (m / idx.length);
    }
    out[i] = s / (tw || 1);
  }
  let lo = Infinity, hi = -Infinity;
  for (const v of out) { if (v < lo) lo = v; if (v > hi) hi = v; }
  const span = hi - lo || 1; for (let i = 0; i < N; i++) out[i] = (out[i] - lo) / span;
  return out;
}
function evalScores() {
  const out = new Float64Array(N);
  let tw = 0; for (const k in state.evW) tw += state.evW[k];
  for (let i = 0; i < N; i++) {
    const rk = R[i].evRank; let s = 0;
    M.evNames.forEach((k, c) => s += (state.evW[k] || 0) * rk[c]);
    out[i] = s / (tw || 1);
  }
