}
function cutTiers(scores, cuts) {
  const sorted = Array.from(scores).sort((a, b) => a - b);
  const c1 = quantile(sorted, cuts[0]), c2 = quantile(sorted, Math.max(cuts[0], cuts[1]));
  return { tiers: Array.from(scores, s => s <= c1 ? 1 : s <= c2 ? 2 : 3), c1, c2 };
}
function kmeansTiers(scores) {
  const w = []; for (const g in groupIdx)
    for (const _ of groupIdx[g].idx) w.push(state.gw[g]);
  const dim = w.length, X = R.map(r => r.rank.map((v, c) => v * w[c]));
  const rnd = mulberry32(state.seed || 13);
  let best = null;
  for (let init = 0; init < 5; init++) {
    const cents = [X[Math.floor(rnd() * N)].slice()];
    while (cents.length < 3) {
      const d2 = X.map(x => Math.min(...cents.map(c => dist2(x, c))));
      let sum = d2.reduce((a, b) => a + b, 0) * rnd(), pick = 0;
      for (let i = 0; i < N; i++) { sum -= d2[i]; if (sum <= 0) { pick = i; break; } }
      cents.push(X[pick].slice());
    }
    const lab = new Int8Array(N);
    for (let it = 0; it < 60; it++) {
      let moved = false;
      for (let i = 0; i < N; i++) {
        let bi = 0, bd = Infinity;
        for (let c = 0; c < 3; c++) { const d = dist2(X[i], cents[c]); if (d < bd) { bd = d; bi = c; } }
        if (lab[i] !== bi) { lab[i] = bi; moved = true; }
      }
      if (!moved) break;
      for (let c = 0; c < 3; c++) {
        const m = new Float64Array(dim); let cnt = 0;
        for (let i = 0; i < N; i++) if (lab[i] === c) { cnt++; for (let d = 0; d < dim; d++) m[d] += X[i][d]; }
        if (cnt) for (let d = 0; d < dim; d++) cents[c][d] = m[d] / cnt;
      }
    }
    let inertia = 0; for (let i = 0; i < N; i++) inertia += dist2(X[i], cents[lab[i]]);
    if (!best || inertia < best.inertia) best = { lab: lab.slice(), inertia };
  }
  const mean = [0, 0, 0], cnt = [0, 0, 0];
  for (let i = 0; i < N; i++) { mean[best.lab[i]] += scores[i]; cnt[best.lab[i]]++; }
  const order = [0, 1, 2].sort((a, b) => mean[a] / (cnt[a] || 1) - mean[b] / (cnt[b] || 1));
  const remap = {}; order.forEach((c, t) => remap[c] = t + 1);
  return Array.from(best.lab, c => remap[c]);
}

function gradeEval(scores) {
  const { tiers, c1, c2 } = cutTiers(scores, state.evCuts);
  for (let i = 0; i < N; i++) {
    const e = R[i].ev;
    if (e.n_tool_errors >= state.ov.errors_t3 || e.n_tool_calls >= state.ov.tool_calls_t3) tiers[i] = 3;
