// (n x 3) cost matrix under the current cost model + prices
function costMatrix() {
  const Cm = new Array(N);
  for (let i = 0; i < N; i++) {
    const e = R[i].ev, T = e.context_tokens, g = e.gen_tokens, n = Math.max(e.n_llm_calls, 1);
    const row = new Float64Array(3);
    for (let t = 1; t <= 3; t++) {
      const [pin, pc, pout] = state.prices[t];
      row[t - 1] = state.costModel === 'cache'
        ? (T * pin + T * (n - 1) / 2 * pc + g * pout) / 1e6
        : (T * pin + g * pout) / 1e6;
    }
    Cm[i] = row;
  }
  return Cm;
}
function evalPolicy(tiers, diffs, Cm) {
  let cost = 0, top = 0, served = 0, wServed = 0, wTot = 0;
  for (let i = 0; i < N; i++) {
    cost += Cm[i][tiers[i] - 1]; top += Cm[i][2];
    const ok = tiers[i] >= diffs[i];
    if (ok) served++;
    wTot += Cm[i][2]; if (ok) wServed += Cm[i][2];
  }
  // top can be 0 if the user zeroes the Tier-3 prices — guard the divisions
  return { costShare: cost / (top || 1), cost, top,
           served: served / N, wServed: wServed / (wTot || 1) };
}

// dispatch rules
function tauTiers(tau) {
  return Array.from({length: N}, (_, i) =>
    CUM[i][0] >= tau ? 1 : CUM[i][1] >= tau ? 2 : 3);
}
function lambdaTiers(lam, Cm) {
  const out = new Array(N);
  for (let i = 0; i < N; i++) {
    const pOver = [1 - CUM[i][0], 1 - CUM[i][1], 0];
    let bt = 1, bv = Infinity;
    for (let t = 1; t <= 3; t++) {
      const v = Cm[i][t - 1] + lam * pOver[t - 1];
      if (v < bv) { bv = v; bt = t; }
    }
    out[i] = bt;
  }
  return out;
}

// ---------- compute ----------
let C = null;
function computeAll() {
  const hS = heuristicScores(), eS = evalScores();
  const { diffs, c1: ec1, c2: ec2 } = gradeEval(eS);
  const Cm = costMatrix();
  const hRank = ranksOf(Array.from(hS));

  let rTiers, rS, rc = null; // rc = score cuts for the histogram
  if (state.method === 'score') {
    rS = hS; const r = cutTiers(rS, state.rCuts); rTiers = r.tiers; rc = [r.c1, r.c2];
  } else if (state.method === 'blend') {
    rS = Float64Array.from({length: N}, (_, i) =>
      state.alpha * mlDiffRank[i] + (1 - state.alpha) * hRank[i]);
    const r = cutTiers(rS, state.rCuts); rTiers = r.tiers; rc = [r.c1, r.c2];
  } else if (state.method === 'ml-tau') {
    rS = mlDiffRank; rTiers = tauTiers(state.tau);
  } else if (state.method === 'ml-lambda') {
    rS = mlDiffRank; rTiers = lambdaTiers(state.lam, Cm);
  } else {
    rS = hS; rTiers = kmeansTiers(hS);
  }

  const conf = [[0,0,0],[0,0,0],[0,0,0]];
  let exact = 0, adj = 0, under = 0, over = 0;
  for (let i = 0; i < N; i++) {
    conf[rTiers[i]-1][diffs[i]-1]++;
    if (rTiers[i] === diffs[i]) exact++;
    if (Math.abs(rTiers[i] - diffs[i]) <= 1) adj++;
    if (rTiers[i] < diffs[i]) under++; else if (rTiers[i] > diffs[i]) over++;
  }
  const pol = evalPolicy(rTiers, diffs, Cm);
  const rho = pearson(ranksOf(Array.from(rS)), ranksOf(Array.from(eS)));
  C = { rS, eS, hS, hRank, rTiers, diffs, rc, ec1, ec2, conf, Cm,
        exact: exact/N, adj: adj/N, under: under/N, over: over/N, rho, ...pol };
}

// reference policies for the comparison overlay ------------------------------
const TIER_MODELS = (window.VIKTOR_FINDINGS || {}).modelTiers?.models || [];
const TIER_OF_MODEL = {};

const TIER_OF_MODEL = {};
TIER_MODELS.forEach(m => TIER_OF_MODEL[m.model] = m.tier);
// tercile-boundary sensitivity: the least-stable Tier-3 member demoted to T2
const TIER_OF_MODEL_ALT = {...TIER_OF_MODEL};
{ const t3 = TIER_MODELS.filter(m => m.tier === 3 && !m.low_confidence)
    .sort((a, b) => a.bootstrap_stability - b.bootstrap_stability)[0];
  if (t3) TIER_OF_MODEL_ALT[t3.model] = 2; }

// FAIR-COMPARISON GRADING for the logged-dispatch point: tool errors and retry
// streaks also drove the tier inference, so a model that logged errors would be
// assigned a low tier AND have its trajectories graded harder — mechanically
// depressing logged served%. For this one comparison, difficulty is graded
// with those two metrics zeroed (weights renormalized) and the error override off.
function gradeStruggleFree() {
  const w = {...state.evW, n_tool_errors: 0, max_repeat_streak: 0};
  let tw = 0; for (const k in w) tw += w[k];
  const scores = new Float64Array(N);
  for (let i = 0; i < N; i++) {
    const rk = R[i].evRank; let s = 0;
    M.evNames.forEach((k, c) => s += (w[k] || 0) * rk[c]);
    scores[i] = s / (tw || 1);
  }
  const { tiers } = cutTiers(scores, state.evCuts);
  for (let i = 0; i < N; i++)
    if (R[i].ev.n_tool_calls >= state.ov.tool_calls_t3) tiers[i] = 3;
  return tiers;
}

function randomLine(diffs, Cm) {
  // expected (cost, served, weighted-served) of random tier assignment,
  // sweeping the mix from all-T1 through uniform to all-T3 — pure expectation
  const pts = [];
  for (let m = 0; m <= 1.0001; m += 0.05) {
    let p;
    if (m <= 0.5) { const t = m * 2; p = [1 - t * 2 / 3, t / 3, t / 3]; }
    else { const t = (m - 0.5) * 2; p = [(1 - t) / 3, (1 - t) / 3, 1 / 3 + t * 2 / 3]; }
    let cost = 0, top = 0, served = 0, ws = 0, wt = 0;
    for (let i = 0; i < N; i++) {
      cost += p[0] * Cm[i][0] + p[1] * Cm[i][1] + p[2] * Cm[i][2];
      top += Cm[i][2];
      const s = diffs[i] <= 1 ? 1 : diffs[i] <= 2 ? p[1] + p[2] : p[2];
      served += s; ws += s * Cm[i][2]; wt += Cm[i][2];
    }
    pts.push([cost / top, served / N, ws / wt]);
  }
  return pts;
}

function loggedPolicy(Cm) {
  if (!Object.keys(TIER_OF_MODEL).length) return null;
  const diffsFair = gradeStruggleFree(); // see gradeStruggleFree: fairness fix
  const tiers = R.map(r => TIER_OF_MODEL[r.model] || 3);
  const main = evalPolicy(tiers, diffsFair, Cm);
  const alt = evalPolicy(R.map(r => TIER_OF_MODEL_ALT[r.model] || 3), diffsFair, Cm);
  // our current policy under the SAME struggle-free grading, for a fair sentence
  const ours = evalPolicy(C.rTiers, diffsFair, Cm);
  return { ...main, alt, ours };
}

// frontier: sweep the active method's own knob; each point = (costShare, served, wServed)
function frontier() {
  const { diffs, Cm, hRank } = C;
  const pts = [];
  const push = tiers => { const p = evalPolicy(tiers, diffs, Cm);
    return pts.push([p.costShare, p.served, p.wServed]); };
  if (state.method === 'ml-tau') {
    for (let tau = 0.30; tau <= 0.996; tau += 0.02) push(tauTiers(tau));
    return { pts, knob: 'τ' };
  }
  if (state.method === 'ml-lambda') {
    for (let k = 0; k < 40; k++) push(lambdaTiers(1e-4 * Math.pow(3e5, k / 39), Cm));
    return { pts, knob: 'λ' };
  }
  // cut-based methods (score / blend): sweep the Tier-3 cut. k-means has no
  // knob of its own — its "frontier" is the heuristic-cut reference sweep,
  // labeled as such so the curve can't impersonate the k-means dots.
  const base = state.method === 'blend'
    ? Float64Array.from({length: N}, (_, i) =>
        state.alpha * mlDiffRank[i] + (1 - state.alpha) * hRank[i])
    : C.hS;
  const sorted = Array.from(base).sort((a, b) => a - b);
  const ratio = state.rCuts[0] / (state.rCuts[1] || 1);
  for (let c2 = 0.30; c2 <= 1.0001; c2 += 0.025) {
    const cc2 = Math.min(c2, 1), q1 = quantile(sorted, cc2 * ratio), q2 = quantile(sorted, cc2);
    push(Array.from(base, s => s <= q1 ? 1 : s <= q2 ? 2 : 3));
  }
  return { pts, knob: state.method === 'kmeans'
    ? 'Tier-3 cut (heuristic reference — k-means itself has no knob)' : 'Tier-3 cut' };
}

